import React, { useState } from "react";
import "./Contact.css";
import { sendEnquiry } from "../sendEnquiry";

function Contact() {
  const [form, setForm] = useState({
    name: "",
    phone: "",
    email: "",
    interest: "",
    message: "",
  });

  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.name || !form.phone || !form.email || !form.interest) {
      alert("Please fill all required fields.");
      return;
    }

    try {
      setLoading(true);

      await sendEnquiry(form);

      alert(
        "Thank you! Your enquiry has been submitted successfully."
      );

      setForm({
        name: "",
        phone: "",
        email: "",
        interest: "",
        message: "",
      });
    } catch (error) {
      console.error("EmailJS Error:", error);

      alert(
        "Enquiry save ho gayi hai, lekin email send nahi ho payi. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="contact-page">

      {/* HERO */}
      <section className="contact-video-hero">

        <video
          className="contact-bg-video"
          autoPlay
          muted
          loop
          playsInline
        >
          <source
            src="/videos/contact-bg.mp4"
            type="video/mp4"
          />
        </video>

        <div className="video-overlay"></div>

        <div className="contact-hero-content">

          <span className="hero-small-title">
            NOIDA EXTENSION PROPERTY
          </span>

          <h1>
            Let's Find Your
            <br />
            <em>Perfect Place.</em>
          </h1>

          <p>
            Whether you're looking to buy, sell, rent or invest,
            we're here to make your real estate journey simple,
            transparent and rewarding.
          </p>

          <div className="hero-actions">

            <a href="#contact-form">
              Start A Conversation →
            </a>

            <a
              href="tel:+919876543210"
              className="call-btn"
            >
              Call An Expert
            </a>

          </div>

        </div>

        <div className="scroll-indicator">
          <span></span>
          SCROLL TO EXPLORE
        </div>

      </section>

      {/* CONTACT AREA */}
      <section
        className="contact-main"
        id="contact-form"
      >

        <div className="contact-wrapper">

          {/* LEFT */}
          <div className="contact-information">

            <span className="section-label">
              GET IN TOUCH
            </span>

            <h2>
              Your Next
              <br />
              <strong>Move Starts Here.</strong>
            </h2>

            <p className="contact-description">
              Have a property requirement or looking for the
              right investment opportunity? Tell us what you're
              looking for and our property experts will get back
              to you.
            </p>

            <div className="contact-details">

              <div className="contact-detail-card">

                <div className="detail-icon">
                  ☎
                </div>

                <div>
                  <small>CALL US</small>
                  <strong>+91 98765 43210</strong>
                  <p>Mon – Sat, 9:00 AM – 7:00 PM</p>
                </div>

              </div>

              <div className="contact-detail-card">

                <div className="detail-icon">
                  ✉
                </div>

                <div>
                  <small>EMAIL US</small>
                  <strong>
                    info@noidaextensionproperty.com
                  </strong>
                  <p>We usually reply within 24 hours</p>
                </div>

              </div>

              <div className="contact-detail-card">

                <div className="detail-icon">
                  ●
                </div>

                <div>
                  <small>VISIT US</small>
                  <strong>Greater Noida West</strong>
                  <p>Uttar Pradesh, India</p>
                </div>

              </div>

            </div>

          </div>

          {/* FORM */}
          <div className="contact-form-card">

            <div className="form-top">

              <span>PROPERTY ENQUIRY</span>

              <h3>
                Tell Us What
                <br />
                You're Looking For.
              </h3>

            </div>

            <form onSubmit={handleSubmit}>

              <div className="form-row">

                <div className="input-group">

                  <label>Your Name</label>

                  <input
                    type="text"
                    name="name"
                    value={form.name}
                    onChange={handleChange}
                    placeholder="Enter your name"
                    required
                  />

                </div>

                <div className="input-group">

                  <label>Phone Number</label>

                  <input
                    type="tel"
                    name="phone"
                    value={form.phone}
                    onChange={handleChange}
                    placeholder="Enter phone number"
                    required
                  />

                </div>

              </div>

              <div className="input-group">

                <label>Email Address</label>

                <input
                  type="email"
                  name="email"
                  value={form.email}
                  onChange={handleChange}
                  placeholder="Enter your email"
                  required
                />

              </div>

              <div className="input-group">

                <label>I'm Interested In</label>

                <select
                  name="interest"
                  value={form.interest}
                  onChange={handleChange}
                  required
                >

                  <option value="">
                    Select your requirement
                  </option>

                  <option>Buy Property</option>
                  <option>Sell Property</option>
                  <option>Rent Property</option>
                  <option>Commercial Property</option>
                  <option>Residential Property</option>
                  <option>Plots</option>
                  <option>PG</option>

                </select>

              </div>

              <div className="input-group">

                <label>Your Message</label>

                <textarea
                  name="message"
                  value={form.message}
                  onChange={handleChange}
                  rows="4"
                  placeholder="Tell us about your property requirement..."
                ></textarea>

              </div>

              <button
                type="submit"
                disabled={loading}
              >
                {loading
                  ? "Sending..."
                  : "Send Enquiry"}

                <span>→</span>
              </button>

            </form>

          </div>

        </div>

      </section>

    </div>
  );
}

export default Contact;
